contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 role, address account) public payable {
        bool reverted;
        try c.renounceRole(role, account) {
            reverted = false;
        } catch {
            reverted = true;
        }
        bool stillMember = c.hasRole(role, account);
        bool expectedRevert = address(this) != account;
        assert(reverted == expectedRevert && (reverted || !stillMember));
    }

    receive() external payable {}
}
